    # Otherwise, compare repeated row-patterns at a common vertical offset.
    best = None
    for d in range(1, h):
        pairs = []
        for i in range(h - d):
            a, b = cells[i], cells[i + d]
            if not a or not b:
                continue
            sim = len(a & b) / min(len(a), len(b))
            if sim >= 0.6:
                pairs.append((i, i + d, sim))
        if len(pairs) < 2:
