        for value in row:
            counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    foreground = max((v for v in counts if v != background),
                     key=lambda v: counts[v], default=background)
    out = [row[:] for row in grid]

    # A full foreground row acts as a reference for shorter left-aligned
    # horizontal runs: mark their missing right-hand continuation.
    full_rows = [r for r in range(h) if all(v == foreground for v in grid[r])]
    if full_rows:
        for r in range(h):
            row = grid[r]
            if row[0] != foreground:
                continue
            end = 0
            while end < w and row[end] == foreground:
                end += 1
            if end < w:
                for c in range(end, w):
                    out[r][c] = 1

    return out
